"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["1251"],{65363(e){e.exports=JSON.parse('{"id":"F467","slug":"bnpl-merchant-breakeven","name":"Buy Now Pay Later: Merchant Break-Even Sales Lift","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Buy now, pay later","level":"Intermediate","aliases":["BNPL","pay in four","merchant fee","conversion uplift"],"formula":{"latex":"\\\\Delta\\\\pi=(1+u)\\\\,(m-f)-m,\\\\quad u^{*}=\\\\frac{f}{m-f}","also":[],"text":"Merchant profit per 100 of base sales = base sales x margin; with BNPL: sales x (1 + lift) x (margin - fee); Break-even lift u* = fee / (margin - fee); Customer pays nothing extra when paid on time, so the lender earns from merchant fees and late fees"},"symbols":[{"symbol":"m","meaning":"Merchant gross margin on a sale","unit":"percent"},{"symbol":"f","meaning":"BNPL fee charged to the merchant","unit":"percent"},{"symbol":"u","meaning":"Increase in sales caused by offering BNPL","unit":"percent"},{"symbol":"u*","meaning":"Smallest increase that leaves the merchant no worse off","unit":"percent"}],"when_to_use":"Use it to decide whether a merchant gains from offering pay-in-installments. The fee is typically higher than a card fee, so sales must rise enough to pay it. For the lender, the merchant fee must cover credit losses, funding and late-payment risk. The calculation counts only merchant profit and ignores returns and repeat purchases.","worked_example":{"problem":"A merchant earns a 25% margin and BNPL costs 4% of each sale. It expects sales to rise 12% with BNPL. The lender sees 2% of balances default.","inputs":{"m":25,"f":4,"u":12,"d":2,"aov":100},"steps":[{"label":"Profit per 100 of base sales","working":"100 x 0.25","value":"25.00"},{"label":"Profit with BNPL per 100 of base sales","working":"100 x (1+0.12) x (0.25-0.04)","value":"23.52"},{"label":"Change in profit","working":"23.52-25","value":"-1.48"},{"label":"Break-even lift = f / (m - f)","working":"0.04 / (0.25-0.04)","value":"19.0%"},{"label":"Lender fee income on one basket","working":"100 x 0.04","value":"4.00"},{"label":"Lender expected default loss on one basket","working":"100 x 0.02","value":"2.00"},{"label":"Lender net before funding and costs","working":"4-2","value":"2.00"}],"answer":"Without BNPL the merchant earns 25.00 per 100 of sales. With a 12% lift it earns 23.52, a change of -1.48. The break-even lift is 19.0%. The lender collects 4.00 in fees on a 100 basket and expects to lose 2.00 from defaults, leaving 2.00."},"calculator":{"available":true,"inputs":[{"id":"m","label":"Merchant margin","unit":"%","type":"number","default":25,"hint":""},{"id":"f","label":"BNPL merchant fee","unit":"%","type":"number","default":4,"hint":""},{"id":"u","label":"Expected sales lift","unit":"%","type":"number","default":12,"hint":""},{"id":"d","label":"Default rate on balances","unit":"%","type":"number","default":2,"hint":""},{"id":"aov","label":"Basket size","unit":"money","type":"number","default":100,"hint":""}],"checks":[{"expr":"m>f","message":"The merchant margin must be larger than the BNPL fee."}],"steps":[{"id":"base","label":"Profit per 100 of base sales","expr":"100*m","format":"money"},{"id":"with_","label":"Profit with BNPL per 100 of base sales","expr":"100*(1+u)*(m-f)","format":"money"},{"id":"chg","label":"Change in profit","expr":"with_-base","format":"money"},{"id":"ustar","label":"Break-even lift = f / (m - f)","expr":"f/(m-f)","format":"pct1"},{"id":"fee","label":"Lender fee income on one basket","expr":"aov*f","format":"money"},{"id":"loss","label":"Lender expected default loss on one basket","expr":"aov*d","format":"money"},{"id":"net","label":"Lender net before funding and costs","expr":"fee-loss","format":"money"}],"results":["chg","ustar","net"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"base":25,"with_":23.520000000000003,"chg":-1.4799999999999969,"ustar":0.1904761904761905,"fee":4,"loss":2,"net":2}},"finder":{"finds":"Whether BNPL pays for the merchant and the lender","needs":"Margin, fee, expected lift, default rate, basket size"},"related":[{"slug":"break-even-analysis","name":"Break-Even Analysis"},{"slug":"expected-unexpected-loss","name":"Expected and Unexpected Credit Loss"},{"slug":"merchant-payment-cost","name":"Merchant Cost of a Digital Payment"}],"related_ids":["F160","F384","F462"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi mathvariant=\\"normal\\">\u0394</mi><mi>\u03C0</mi><mo>=</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>u</mi><mo stretchy=\\"false\\">)</mo><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mi>m</mi><mo>\u2212</mo><mi>f</mi><mo stretchy=\\"false\\">)</mo><mo>\u2212</mo><mi>m</mi><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><msup><mi>u</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mfrac><mi>f</mi><mrow><mi>m</mi><mo>\u2212</mo><mi>f</mi></mrow></mfrac></mrow><annotation encoding=\\"application/x-tex\\">\\\\Delta\\\\pi=(1+u)\\\\,(m-f)-m,\\\\quad u^{*}=\\\\frac{f}{m-f}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"bull-call-spread","name":"Bull Call Spread"},"next":{"slug":"buyout-value-creation","name":"Buyout Returns and Value Creation Bridge"},"lesson":null,"total":522}')}}]);